        hash.remove(0);

        // verify that the mapping remains consistent
        for (Map.Entry<Integer, Integer> e : before.entrySet()) {
            int m = hash.lookup(e.getKey());
            assertTrue(e.getValue() == 0 || e.getValue() == m);
        }
