         */
        private int ceil(CronTab c, int n) {
            long bits = bits(c);
            while ((bits | (1L << n)) != bits) {
                if (n > 60)   return -1;
                n++;
            }
            return n;
        }

        /**
         * Given a bit mask, finds the first bit that's on, and return its index.
         */
        private int first(CronTab c) {
            return ceil(c, 0);
        }

        private int floor(CronTab c, int n) {
            long bits = bits(c);
            while ((bits | (1L << n)) != bits) {
                if (n == 0)   return -1;
                n--;
            }
            return n;
